data.exp1.json:
{
 "uid": "exp1asr",
 "title": "EXP-1 ASR: L-1 latencia y D-3 doble reserva",
 "schemaVersion": 39,
 "version": 8,
 "refresh": "5s",
 "time": {
  "from": "now-20m",
  "to": "now"
 },
 "panels": [
  {
   "id": 1,
   "type": "row",
   "title": "L-1  Latencia de reservar: p95 \u2264 150 ms",
   "gridPos": {
    "x": 0,
    "y": 0,
    "w": 24,
    "h": 1
   },
   "collapsed": false
  },
  {
   "id": 2,
   "type": "stat",
   "title": "p95 (ventana 5 min)",
   "description": "Verde = cumple el ASR (\u2264150 ms). Rojo = lo incumple.",
   "gridPos": {
    "x": 0,
    "y": 1,
    "w": 5,
    "h": 6
   },
   "datasource": {
    "type": "prometheus",
    "uid": "prom"
   },
   "fieldConfig": {
    "defaults": {
     "unit": "s",
     "thresholds": {
      "mode": "absolute",
      "steps": [
       {
        "color": "green",
        "value": null
       },
       {
        "color": "red",
        "value": 0.15
       }
      ]
     },
     "color": {
      "mode": "thresholds"
     },
     "decimals": 3
    },
    "overrides": []
   },
   "targets": [
    {
     "expr": "histogram_quantile(0.95, sum(rate(taq_reservar_seconds_bucket[5m])) by (le))",
     "instant": true,
     "refId": "A",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    }
   ],
   "options": {
    "reduceOptions": {
     "calcs": [
      "lastNotNull"
     ]
    },
    "colorMode": "background",
    "graphMode": "none"
   }
  },
  {
   "id": 3,
   "type": "stat",
   "title": "Solicitudes recibidas en el rango",
   "description": "Solicitudes de reserva que entraron al gateway dentro del rango de tiempo del tablero (con la vista reiniciada, desde el reinicio).",
   "gridPos": {
    "x": 5,
    "y": 1,
    "w": 5,
    "h": 6
   },
   "datasource": {
    "type": "prometheus",
    "uid": "prom"
   },
   "fieldConfig": {
    "defaults": {
     "unit": "short",
     "thresholds": {
      "mode": "absolute",
      "steps": [
       {
        "color": "blue",
        "value": null
       }
      ]
     },
     "color": {
      "mode": "thresholds"
     },
     "decimals": 0
    },
    "overrides": []
   },
   "targets": [
    {
     "expr": "sum(taq_reservar_seconds_count) - (sum(taq_reservar_seconds_count offset $__range) or vector(0))",
     "instant": true,
     "refId": "A",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    }
   ],
   "options": {
    "reduceOptions": {
     "calcs": [
      "lastNotNull"
     ]
    },
    "colorMode": "background",
    "graphMode": "none"
   }
  },
  {
   "id": 4,
   "type": "timeseries",
   "title": "p95 en el tiempo vs. l\u00edmite del ASR",
   "description": "",
   "gridPos": {
    "x": 10,
    "y": 1,
    "w": 14,
    "h": 6
   },
   "datasource": {
    "type": "prometheus",
    "uid": "prom"
   },
   "fieldConfig": {
    "defaults": {
     "unit": "s"
    },
    "overrides": []
   },
   "targets": [
    {
     "expr": "histogram_quantile(0.95, sum(rate(taq_reservar_seconds_bucket[30s])) by (le))",
     "legendFormat": "p95 reservar",
     "refId": "A",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    },
    {
     "expr": "vector(0.15)",
     "legendFormat": "l\u00edmite ASR 150 ms",
     "refId": "B",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    }
   ]
  },
  {
   "id": 5,
   "type": "row",
   "title": "D-3  Una silla, una sola reserva: cuando llegan varias solicitudes a la misma silla solo una se aprueba",
   "gridPos": {
    "x": 0,
    "y": 7,
    "w": 24,
    "h": 1
   },
   "collapsed": false
  },
  {
   "id": 6,
   "type": "timeseries",
   "title": "Solicitudes simult\u00e1neas a una misma silla en el tiempo",
   "description": "Plano en 0 mientras no hay disputa. Cada pico es una r\u00e1faga: varios compradores pidiendo la misma silla a la vez (se mantiene ~12 s para que se alcance a ver).",
   "gridPos": {
    "x": 0,
    "y": 8,
    "w": 15,
    "h": 9
   },
   "datasource": {
    "type": "prometheus",
    "uid": "prom"
   },
   "fieldConfig": {
    "defaults": {
     "unit": "short",
     "min": 0,
     "decimals": 0,
     "color": {
      "mode": "fixed",
      "fixedColor": "purple"
     },
     "custom": {
      "drawStyle": "line",
      "lineInterpolation": "stepAfter",
      "fillOpacity": 30,
      "lineWidth": 2,
      "showPoints": "never"
     }
    },
    "overrides": []
   },
   "targets": [
    {
     "expr": "taq_conflicto_pico_misma_silla",
     "legendFormat": "solicitudes a la misma silla",
     "refId": "A",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    }
   ]
  },
  {
   "id": 7,
   "type": "timeseries",
   "title": "Solicitudes en conflicto por tiempo: aprobadas vs. no aprobadas",
   "description": "Valores exactos de la \u00faltima r\u00e1faga (se mantienen ~12 s): 1 verde (aprobada) + el resto rojo (no aprobadas) = total de solicitudes de la r\u00e1faga.",
   "gridPos": {
    "x": 15,
    "y": 8,
    "w": 9,
    "h": 9
   },
   "datasource": {
    "type": "prometheus",
    "uid": "prom"
   },
   "fieldConfig": {
    "defaults": {
     "unit": "short",
     "min": 0,
     "decimals": 0,
     "custom": {
      "drawStyle": "bars",
      "fillOpacity": 85,
      "lineWidth": 1,
      "stacking": {
       "mode": "normal"
      },
      "barAlignment": 0
     }
    },
    "overrides": [
     {
      "matcher": {
       "id": "byName",
       "options": "aprobadas"
      },
      "properties": [
       {
        "id": "color",
        "value": {
         "mode": "fixed",
         "fixedColor": "green"
        }
       }
      ]
     },
     {
      "matcher": {
       "id": "byName",
       "options": "no aprobadas"
      },
      "properties": [
       {
        "id": "color",
        "value": {
         "mode": "fixed",
         "fixedColor": "red"
        }
       }
      ]
     }
    ]
   },
   "targets": [
    {
     "expr": "taq_rafaga_aprobadas",
     "legendFormat": "aprobadas",
     "refId": "A",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    },
    {
     "expr": "taq_rafaga_canceladas",
     "legendFormat": "no aprobadas",
     "refId": "B",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    }
   ]
  },
  {
   "id": 8,
   "type": "table",
   "title": "Sillas en disputa: cu\u00e1ntas solicitudes se cancelaron por cada silla",
   "description": "Cada fila es una silla con conflicto; 'Cancelada' = solicitudes rechazadas (la ganadora no aparece: fue confirmada).",
   "gridPos": {
    "x": 0,
    "y": 17,
    "w": 24,
    "h": 8
   },
   "datasource": {
    "type": "prometheus",
    "uid": "prom"
   },
   "fieldConfig": {
    "defaults": {
     "unit": "short"
    },
    "overrides": []
   },
   "targets": [
    {
     "expr": "sort_desc(sum(taq_bloqueo_rechazo_asiento_total) by (asiento, motivo) - (sum(taq_bloqueo_rechazo_asiento_total offset $__range) by (asiento, motivo) or sum(taq_bloqueo_rechazo_asiento_total) by (asiento, motivo) * 0))",
     "instant": true,
     "format": "table",
     "refId": "A",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    }
   ],
   "options": {
    "cellHeight": "sm",
    "sortBy": [
     {
      "displayName": "Canceladas",
      "desc": true
     }
    ]
   },
   "transformations": [
    {
     "id": "organize",
     "options": {
      "excludeByName": {
       "Time": true
      },
      "renameByName": {
       "asiento": "Silla",
       "motivo": "Motivo",
       "Value": "Canceladas"
      }
     }
    }
   ]
  },
  {
   "id": 9,
   "type": "row",
   "title": "D-3  Vencimiento del bloqueo a los 8 min",
   "gridPos": {
    "x": 0,
    "y": 25,
    "w": 24,
    "h": 1
   },
   "collapsed": false
  },
  {
   "id": 10,
   "type": "timeseries",
   "title": "Bloqueos activos y liberados por vencimiento",
   "description": "",
   "gridPos": {
    "x": 0,
    "y": 26,
    "w": 24,
    "h": 7
   },
   "datasource": {
    "type": "prometheus",
    "uid": "prom"
   },
   "fieldConfig": {
    "defaults": {
     "unit": "short"
    },
    "overrides": []
   },
   "targets": [
    {
     "expr": "taq_bloqueos_activos",
     "legendFormat": "bloqueos activos",
     "refId": "A",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    },
    {
     "expr": "taq_bloqueo_liberados_total",
     "legendFormat": "liberados por vencimiento (acum.)",
     "refId": "B",
     "datasource": {
      "type": "prometheus",
      "uid": "prom"
     }
    }
   ]
  }
 ]
}
